function render(ctx) {
  const d = ctx.data;
  const small = ctx.family === 'small';
  const days = d.days.slice(small ? -28 : -35);
  const cell = small ? 14 : 18;
  const gap = small ? 3 : 4;

  const weeks = [];
  for (let i = 0; i < days.length; i += 7) {
    weeks.push({ type: 'hstack', spacing: gap, children: days.slice(i, i + 7).map(day => ({
      type: 'rect', cornerRadius: cell / 4,
      fill: day.count > 0 ? '#34C759' : '#FFFFFF1F',
      stroke: day.date === ctx.today.date ? { color: '#FFFFFF', width: 1.5 } : null,
      frame: { width: cell, height: cell },
    })) });
  }

  const check = d.today
    ? { type: 'button', action: 'uncheck', rowId: d.today.id, children: [
        { type: 'symbol', name: 'checkmark.circle.fill', size: 30, color: '#34C759' } ] }
    : { type: 'button', action: 'check', children: [
        { type: 'symbol', name: 'circle', size: 30, color: '#FFFFFF99' } ] };

  const header = { type: 'vstack', align: 'leading', spacing: 2, children: [
    { type: 'text', value: 'Meditate', size: 15, weight: 'bold', color: '#FFFFFF', lineLimit: 1 },
    { type: 'text', value: d.streak + (d.streak === 1 ? ' day' : ' days'), size: 12,
      color: '#FFFFFFB3', lineLimit: 1 },
  ] };

  const grid = { type: 'vstack', spacing: gap, children: weeks };
  const frame = { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' };

  if (small) {
    return { type: 'vstack', align: 'leading', spacing: 8, padding: 14, frame, widgetBackground: '#1C1C1E',
      children: [{ type: 'hstack', children: [header, { type: 'spacer' }, check] }, { type: 'spacer' }, grid] };
  }
  return { type: 'hstack', spacing: 16, padding: 14, frame, widgetBackground: '#1C1C1E',
    children: [
      { type: 'vstack', align: 'leading', frame: { maxHeight: 'infinity', alignment: 'topLeading' },
        children: [header, { type: 'spacer' }, check] },
      { type: 'spacer' },
      grid,
    ] };
}
